-- habanos_presence|cameroon|description|ar — superlatif « أكثر ... طلبًا » interdit ; Habanos en latin
UPDATE `habanos_presence` SET `description_ar` = 'ليس للكاميرون تمثيل لدى Habanos، وهي لا تنتج سيجارًا جاهزًا للسوق الدولية. إسهامها واحد لكنه جوهري: غلاف الكاميرون، الذي ينمو على السفوح البركانية لجبل الكاميرون. وهو من الأغلفة المطلوبة بشدة في العالم، ولا سيما في Arturo Fuente Hemingway وOliva Serie G. ويبقى الإنتاج محدودًا جدًا ومتقلّبًا بحسب مواسم الأمطار.'
