-- habanos_presence|indonesia|description|ar — superlatif « أكثر » interdit ; « milieu de gamme » précisé ; Habanos en latin
UPDATE `habanos_presence` SET `description_ar` = 'ليس لإندونيسيا تمثيل لدى Habanos. إسهامها الرئيس هو غلاف دلي سومطرة، المزروع في تربة بركانية منذ المزارع الهولندية في القرن التاسع عشر. وهو ترابيّ متبَّل قليلًا، ومن الأغلفة الشائعة الاستعمال في السيجاريّو وسيجار الفئة المتوسطة في أوروبا.'
