-- habanos_presence|nicaragua|description|ar — superlatifs « أكبر » et « كبرى » interdits
UPDATE `habanos_presence` SET `description_ar` = 'أصبحت نيكاراغوا أول منتج للسيجار الفاخر في العالم من حيث الحجم، متجاوزةً كوبا وجمهورية الدومينيكان. تتركّز الصناعة حول إستيلي — «عاصمة السيجار» — حيث مصانع الدور الكبيرة. وخلافًا لكوبا، الصناعة النيكاراغوية خاصة بالكامل وشديدة التنافس.'
 WHERE `country_id` = 'nicaragua' AND SHA1(TRIM(`description`)) = 'f56557cc545ce9bae28ab30d7c8bbe917f145c84';
