-- habanos_presence|panama|description|ar — Habanos et nom d'usine en latin
UPDATE `habanos_presence` SET `description_ar` = 'لا يوجد في بنما تمثيل لـHabanos. بدأت صناعة السيجار الفاخر فيها في آذار/مارس 1981، حين جلب غيلبرتو أوليفا ونستور بلاسينسيا بذورًا كوبية إلى مقاطعة كوكلي: افتُتح Coclé Tobacco Factory في بينونومي في العام نفسه، وTabacos Panamá S.A. في لا بينتادا سنة 1984، وأسّست مِريام باديّا شركة Joyas de Panamá في شباط/فبراير 1986. ويُزرع التبغ في تشيريكي. وقد انهارت هذه الصناعة اليوم إلى حدّ بعيد — سوء إدارة، واتّهامات باحتيال على الشهادات الضريبية، وأجور غير مدفوعة — ووجد تحقيق صحفي سنة 2025 خرج بحثًا عن السيجار البنمي الورشَ متوقّفة. لذلك لا يحمل هذا الأطلس أيّ بطاقة لدار بنمية: ليس لديه مصدر متين بما يكفي لكتابتها.'
 WHERE `country_id` = 'panama' AND SHA1(TRIM(`description`)) = '1e3d2831bf397234da1e959f1be0f9ba00df0c67';
