 WHERE `entite` = 'habanos_presence' AND `entite_id` = 'panama' AND `champ` = 'description' AND `lang` = 'ar' AND `source_hash` = '1e3d2831bf397234da1e959f1be0f9ba00df0c67';
-- habanos_presence|philippines|description|ar — superlatif « أقدم » interdit, reformulé ; Habanos en latin
UPDATE `habanos_presence` SET `description_ar` = 'لا يوجد في الفلبين تمثيل لـHabanos. وهي صناعة تبغ ضاربة في القِدم في العالم (احتكار إسباني منذ 1782)، غير أنها اليوم غير مستثمَرة دوليًا بما يكفي. ويحمل تروا وادي كاغايان إمكانات فاخرة حقيقية لا تزال غير مستغلّة إلى حد بعيد. والسوق محلية في معظمها.'
